import { ref, onMounted, onBeforeUnmount } from 'vue';
import axios from 'axios';
import { ElMessage } from 'element-plus';

// 引入容器列表组件
import DockerContainers from '@/components/Container/DockerContainers.vue';
export default {
  __name: 'MonitorView',
  setup(__props, {
    expose: __expose
  }) {
    __expose();
    const containerRef = ref(); // 访问ContainerList组件
    const containers = ref([]); // 容器数据
    const selectedContainer = ref(''); // 当前选择的容器

    const networkStats = ref(null);
    const bandwidth = ref(null);
    let intervalId = null;

    // 拉取容器列表
    const fetchContainers = async () => {
      try {
        await containerRef.value.fetchContainers();
        containers.value = containerRef.value.containers;
      } catch (err) {
        console.error('拉取容器列表失败', err);
      }
    };

    // 拉取指定容器的网络状态
    const fetchStats = async () => {
      if (!selectedContainer.value) return;
      try {
        const [netRes, bwRes] = await Promise.all([axios.get(`http://localhost:8081/stats/networkStats/${selectedContainer.value}`), axios.get(`http://localhost:8081/stats/bandwidth/${selectedContainer.value}`)]);
        networkStats.value = netRes.data;
        bandwidth.value = bwRes.data;
      } catch (err) {
        ElMessage.error('获取监控数据失败');
        console.error(err);
      }
    };

    // 持续刷新
    onMounted(async () => {
      await fetchContainers();
      intervalId = setInterval(fetchStats, 1000);
    });
    onBeforeUnmount(() => {
      clearInterval(intervalId);
    });
    const __returned__ = {
      containerRef,
      containers,
      selectedContainer,
      networkStats,
      bandwidth,
      get intervalId() {
        return intervalId;
      },
      set intervalId(v) {
        intervalId = v;
      },
      fetchContainers,
      fetchStats,
      ref,
      onMounted,
      onBeforeUnmount,
      get axios() {
        return axios;
      },
      get ElMessage() {
        return ElMessage;
      },
      DockerContainers
    };
    Object.defineProperty(__returned__, '__isScriptSetup', {
      enumerable: false,
      value: true
    });
    return __returned__;
  }
};
